int16_t ECOCALLMETHOD lab_bitonic_sort(IEcoLab64* me, void* base, uint32_t count, uint32_t width, BitonicCompare compare, uint32_t workers, BitonicExecutor executor, void* executor_context, BitonicStats* stats) {
    IEcoMemoryAllocator1* allocator;
    uint32_t N;
    uint32_t k;
    uint32_t j;
    uint32_t i;
    uint32_t stage;
    uint32_t pairs;
    uint32_t* indices;
    void* output;
    int16_t status;

    if (!me || !compare || !stats) return -1;
    if (width == 0 || count > 1048576) return -1;
    if (count > 0 && (!base || width > 0xFFFFFFFFU / count)) return -1;
    if (workers < 1 || workers > 16) return -1;
    if (workers > 1 && !executor) return -1;

    if (count <= 1) {
        stats->padded_count = count;
        stats->stages = 0;
        stats->network_pairs = 0;
        return 0;
    }

    N = 1;
    while (N < count) {
        N <<= 1;
    }

    allocator = lab_allocator(me);
    if (!allocator) return -2;

    indices = (uint32_t*)allocator->Alloc(allocator, N * sizeof(uint32_t));
    if (!indices) return -2;

    for (i = 0; i < count; i++) {
        indices[i] = i;
    }

    for (i = count; i < N; i++) {
        indices[i] = count;
    }

    StageContext context;
    context.indices = indices;
    context.base = (const unsigned char*)base;
    context.width = width;
    context.count = count;
    context.N = N;

    stages = 0;
    pairs = 0;

    for (k = 2; k <= N; k <<= 1) {
        for (j = k >> 1; j > 0; j >>= 1) {
            context.k = k;
            context.j = j;
            if (workers == 1) {
                stage_job(&context, 0, 1);
            } else {
                status = executor(executor_context, stage_job, &context, workers);
                if (status != 0) {
                    allocator->Free(allocator, indices);
                    return -3;
                }
            }
            stages++;
            pairs += N / 2;
        }
    }

    stats->padded_count = N;
    stats->stages = stages;
    stats->network_pairs = pairs;

    output = allocator->Alloc(allocator, count * width);
    if (!output) {
        allocator->Free(allocator, indices);
        return -2;
    }

    for (i = 0; i < count; i++) {
        allocator->Copy(allocator, output, base + indices[i] * width, width);
    }

    allocator->Copy(allocator, base, output, count * width);
    allocator->Free(allocator, output);
    allocator->Free(allocator, indices);

    return 0;
}

